"""FENIX CPU controller: wire validation and certified epoch planning.

The classifier modules, probability compiler and metric routines are supplied
CPU components.  This module performs strict request validation and drives the
planner (see planner.py) for every epoch of the batch.
"""
import json

MAX_INPUT = 16 * 1024 * 1024


class Invalid(Exception):
    pass


def _no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid('duplicate key')
        d[k] = v
    return d


def _bad_const(_):
    raise Invalid('nonfinite')


def _bad_float(_):
    raise Invalid('noninteger number')


def _need_int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        raise Invalid('integer out of range')
    return v


CASE_KEYS = frozenset((
    'model', 'class_values', 'stats', 'bucket', 'slots', 'flows', 'groups',
    'windows'))


def parse_request(raw):
    if type(raw) is not bytes:
        raise Invalid('input type')
    if len(raw) > MAX_INPUT:
        raise Invalid('input size')
    try:
        text = raw.decode('utf-8')
    except Exception:
        raise Invalid('utf-8')
    try:
        return json.loads(text, object_pairs_hook=_no_dup,
                          parse_constant=_bad_const, parse_float=_bad_float)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')

